import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Table, Badge } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { userAPI } from '../../services/api';
import { getUser } from '../../utils/auth';

const UserDashboard = () => {
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0
  });
  const [recentBookings, setRecentBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const user = getUser();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching user dashboard data...');
      const response = await userAPI.getMyBookings();
      console.log('📊 User dashboard API response:', response);
      
      // Handle nested response structure
      let bookings = response.data;
      if (response.data && response.data.data) {
        bookings = response.data.data;
      }
      
      console.log('📋 Bookings data:', bookings);
      
      // Ensure bookings is an array
      if (!Array.isArray(bookings)) {
        console.warn('⚠️ Bookings is not an array, setting to empty array');
        bookings = [];
      }

      // Calculate stats
      const stats = {
        total: bookings.length,
        pending: bookings.filter(b => b.status === 'pending').length,
        approved: bookings.filter(b => b.status === 'approved').length,
        rejected: bookings.filter(b => b.status === 'rejected').length
      };

      setStats(stats);
      setRecentBookings(bookings.slice(0, 5)); // Show last 5 bookings
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      toast.error('Gagal memuat data dashboard');
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    return <Badge bg={variants[status]}>{status.toUpperCase()}</Badge>;
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Dashboard User</h2>
          <p className="text-muted">Selamat datang, {user?.name || user?.email}!</p>
        </Col>
        <Col xs="auto">
          <Button as={Link} to="/user/booking" variant="primary">
            <i className="fas fa-plus me-2"></i>
            Buat Booking Baru
          </Button>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col md={3}>
          <Card className="text-center h-100">
            <Card.Body>
              <i className="fas fa-calendar-alt fa-2x text-primary mb-2"></i>
              <h3>{stats.total}</h3>
              <p className="text-muted mb-0">Total Booking</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center h-100">
            <Card.Body>
              <i className="fas fa-clock fa-2x text-warning mb-2"></i>
              <h3>{stats.pending}</h3>
              <p className="text-muted mb-0">Menunggu</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center h-100">
            <Card.Body>
              <i className="fas fa-check-circle fa-2x text-success mb-2"></i>
              <h3>{stats.approved}</h3>
              <p className="text-muted mb-0">Disetujui</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center h-100">
            <Card.Body>
              <i className="fas fa-times-circle fa-2x text-danger mb-2"></i>
              <h3>{stats.rejected}</h3>
              <p className="text-muted mb-0">Ditolak</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Bookings */}
      <Row>
        <Col>
          <Card>
            <Card.Header className="d-flex justify-content-between align-items-center">
              <h5 className="mb-0">Booking Terbaru</h5>
              <Button as={Link} to="/user/mybookings" variant="outline-primary" size="sm">
                Lihat Semua
              </Button>
            </Card.Header>
            <Card.Body>
              {recentBookings.length > 0 ? (
                <Table responsive>
                  <thead>
                    <tr>
                      <th>Judul</th>
                      <th>Tanggal</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentBookings.map((booking) => (
                      <tr key={booking.id}>
                        <td>{booking.title}</td>
                        <td>{new Date(booking.date).toLocaleDateString('id-ID')}</td>
                        <td>{booking.start_time} - {booking.end_time}</td>
                        <td>
                          <Badge bg="info">{booking.request_type}</Badge>
                        </td>
                        <td>{getStatusBadge(booking.status)}</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-4">
                  <i className="fas fa-calendar-times fa-3x text-muted mb-3"></i>
                  <p className="text-muted">Belum ada booking</p>
                  <Button as={Link} to="/user/booking" variant="primary">
                    Buat Booking Pertama
                  </Button>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default UserDashboard;
